questionvariables.text:
/* ---------- DATA: blue and red pens used by grades 7 to 11 ----------
   Pool entry = [u, b7..b11, r7..r11].  u is the vertical grid spacing (5, 10 or 20) and every value is a whole multiple of u,
   so every point sits exactly on a grid line.  Each data set is vetted so that:
     * the grade with the highest TOTAL (blue + red), the grade with the greatest DIFFERENCE |blue - red| and the grade with the
       smallest difference are three different grades, each unique, so the answers cannot be confused;
     * the greatest difference is not itself a grade number (7 to 11) and the blue total is not either;
     * blue and red never coincide in a grade, so both markers are always visible;
     * the red line follows exactly one of five clear patterns (13 data sets of each):
         1 rises every step   2 falls every step   3 rises then falls (one peak)   4 falls then rises (one low point)   5 zigzag
     * the wrong totals used for feedback (red total, blue+red total, blue total without grade 7 or without grade 11) are all different. */
pool : [
    [10,50,90,40,50,80,80,60,50,30,20],
    [20,100,40,20,100,160,160,120,100,60,40],
    [10,70,80,90,40,50,20,40,50,60,80],
    [10,30,90,20,20,20,40,50,60,70,90],
    [10,30,20,50,20,90,90,30,10,50,60],
    [20,40,100,140,100,120,100,60,120,140,160],
    [20,180,20,80,40,80,20,100,60,80,160],
    [20,120,160,140,140,140,140,60,80,180,60],
    [5,10,40,15,45,25,45,20,35,5,15],
    [5,15,45,5,15,5,10,20,25,30,35],
    [20,60,180,160,40,140,80,100,120,160,180],
    [10,20,90,20,30,70,10,30,40,50,90],
    [5,40,35,5,10,25,5,20,30,35,45],
    [20,180,160,60,20,20,120,60,20,100,180],
    [10,80,20,40,60,60,20,50,70,90,70],
    [5,20,15,45,10,30,5,10,20,40,5],
    [5,5,20,10,40,15,45,40,35,25,10],
    [5,25,10,45,40,10,45,5,10,25,30],
    [10,90,30,20,20,40,60,40,50,60,70],
    [10,90,80,10,10,20,20,60,90,20,80],
    [10,90,50,60,80,80,70,60,90,10,60],
    [10,50,70,60,80,20,70,40,30,20,30],
    [20,100,60,140,100,120,180,160,100,80,60],
    [20,60,140,40,100,20,40,80,120,140,160],
    [20,100,60,140,180,120,140,80,60,20,40],
    [10,40,40,70,20,90,80,50,40,70,50],
    [10,40,90,20,30,70,80,70,40,10,60],
    [10,70,70,10,80,20,30,90,60,50,30],
    [10,90,40,10,10,30,10,30,40,80,90],
    [10,90,40,60,10,10,20,30,40,80,90],
    [10,10,20,80,50,50,80,60,40,30,20],
    [10,20,60,80,90,80,50,90,60,50,30],
    [5,25,40,15,25,30,35,5,10,35,45],
    [20,20,100,100,180,100,160,140,120,100,60],
    [10,90,60,50,70,60,10,90,70,40,70],
    [10,10,90,30,10,70,20,60,70,30,10],
    [20,140,160,180,60,120,180,140,120,100,80],
    [20,40,120,120,100,180,20,60,160,140,80],
    [10,20,50,80,70,90,60,70,50,40,10],
    [10,50,70,90,10,20,10,60,50,90,80],
    [20,140,60,40,40,40,20,40,100,140,120],
    [5,25,45,30,15,30,10,15,25,30,45],
    [10,90,40,80,30,80,50,30,50,90,40],
    [10,30,50,80,70,10,90,70,50,30,20],
    [10,10,40,60,20,40,80,30,40,70,90],
    [20,40,80,100,160,140,180,160,140,100,60],
    [10,60,40,10,50,90,50,80,60,30,10],
    [10,80,20,90,30,60,60,50,30,20,10],
    [5,25,45,10,30,30,40,5,20,10,45],
    [10,80,70,50,30,30,10,20,30,70,80],
    [10,40,80,60,40,10,20,40,50,60,90],
    [20,100,60,20,20,80,140,100,180,80,100],
    [20,20,20,100,180,140,160,120,80,120,80],
    [10,70,70,40,20,90,20,50,90,80,60],
    [5,20,20,30,10,45,45,30,25,20,15],
    [5,25,5,10,35,40,45,35,25,15,5],
    [20,140,80,140,100,180,20,100,180,160,120],
    [10,30,20,80,70,40,80,60,50,10,50],
    [10,20,40,10,10,90,90,60,50,20,70],
    [20,20,40,60,80,160,160,120,100,60,40],
    [10,70,20,10,40,50,20,30,50,70,80],
    [5,5,15,35,40,35,30,35,45,35,15],
    [10,60,90,40,50,30,20,50,60,10,80],
    [20,180,120,80,20,20,40,100,180,140,60],
    [20,160,80,140,20,80,120,60,100,120,140]
];
cfg : rand(pool);
uu : cfg[1];
B : [cfg[2], cfg[3], cfg[4], cfg[5], cfg[6]];       /* blue pens, grades 7..11 */
R : [cfg[7], cfg[8], cfg[9], cfg[10], cfg[11]];     /* red pens, grades 7..11 */
grades : [7, 8, 9, 10, 11];
TT : create_list(B[i] + R[i], i, 1, 5);             /* totals */
DD : create_list(abs(B[i] - R[i]), i, 1, 5);        /* differences */
gpos(L, v) := first(sublist_indices(L, lambda([x], is(x = v)))) + 6;     /* grade where the list L has the value v */
gmaxT : gpos(TT, lmax(TT));   gmaxD : gpos(DD, lmax(DD));   gminD : gpos(DD, lmin(DD));
gmaxB : gpos(B, lmax(B));     gmaxR : gpos(R, lmax(R));     gminR : gpos(R, lmin(R));
dmax : lmax(DD);   tmax : lmax(TT);
sumB : apply("+", B);   sumR : apply("+", R);   sumT : sumB + sumR;
Ytop : lmax(append(B, R)) + uu;                     /* top of the vertical axis */
ut : 2*uu;   Ytop2 : ut*ceiling(tmax/ut) + ut;      /* scale used for the bar chart of totals */

/* the red line: change at each step, and its pattern */
dif : create_list(R[i+1] - R[i], i, 1, 4);
sg : map(signum, dif);
nchg : length(sublist(create_list(i, i, 1, 3), lambda([i], is(sg[i] # sg[i+1]))));
trend : if is(lmin(sg) = 1) then 1 else if is(lmax(sg) = -1) then 2 else if is(nchg = 1 and sg[1] = 1) then 3 else if is(nchg = 1 and sg[1] = -1) then 4 else 5;
allR : is(length(sublist(create_list(R[i] - B[i], i, 1, 5), lambda([x], is(x > 0)))) = 5);    /* red above blue in every grade */
allB : is(length(sublist(create_list(B[i] - R[i], i, 1, 5), lambda([x], is(x > 0)))) = 5);    /* blue above red in every grade */

/* ---------- (a) dropdown: the grade with the highest total ---------- */
ta1 : create_list([g, is(g = gmaxT), sconcat("Grade ", string(g))], g, grades);
/* ---------- (b) and (c): numbers ---------- */
ta2 : gmaxD;
ta3 : sumB;
/* ---------- (d) radio: the pattern of the red line ---------- */
ta4 : random_permutation([
 [1, is(trend=1), "It rises at every step: each grade used more red pens than the grade before."],
 [2, is(trend=2), "It falls at every step: each grade used fewer red pens than the grade before."],
 [3, is(trend=3), sconcat("It rises at first to a peak (the most red pens) in grade ", string(gmaxR), ", and then falls.")],
 [4, is(trend=4), sconcat("It falls at first to a low point (the fewest red pens) in grade ", string(gminR), ", and then rises.")],
 [5, is(trend=5), "It goes up and down more than once: it changes direction at least twice."]
]);
/* ---------- (e) checkbox: reasons why the number of pens could vary between grades ---------- */
Spool : [
 [1,  true,  "Different grades have different numbers of students, so a grade with more students will use more pens."],
 [2,  true,  "The amount of written work (notes, homework and tests) can differ from grade to grade, so the number of pens used differs too."],
 [3,  true,  "Teachers in different grades ask for different kinds of writing and marking, so blue and red pens are used in different amounts."],
 [4,  true,  "Students' habits change as they get older (for example how they underline, draw diagrams or correct their work), so pen use changes between grades."],
 [5,  true,  sconcat("Grade ", string(gmaxT), " used the most pens in total (", string(tmax), "), which could be because that grade has more students or more written work.")],
 [11, false, "Every grade must use exactly the same number of pens, so any difference on the graph must be a mistake."],
 [12, false, "Blue and red pens are made in equal numbers, so each grade must use as many blue pens as red pens."],
 [13, false, "The number of pens used is decided only by the grade number, so it must go up by the same amount from each grade to the next."],
 [21, allR,  "Red pens are used more than blue pens in every grade, which could be because teachers mark and correct work in red."],
 [22, allB,  "Blue pens are used more than red pens in every grade, which could be because students write most of their work in blue and keep red for occasional corrections."],
 [23, is(trend=1), "Red pen use rises with every grade, which could be because older students have more work to correct and mark."],
 [24, is(trend=2), "Red pen use falls with every grade, which could be because older students are asked to keep to blue or black ink."]
];
Tr : sublist(Spool, lambda([r], second(r)));
Fa : sublist(Spool, lambda([r], not second(r)));
nt : min(rand([2,3,4]), length(Tr));
Tsel : rand_selection(Tr, nt);
Fsel : rand_selection(Fa, 6 - nt);
ta5 : random_permutation(append(Tsel, Fsel));
tk : map(first, Tsel);   wk : map(first, Fsel);

/* values used only in question tests */
gone : first(listify(setdifference({gmaxB, gmaxR}, {gmaxT})));                            /* a colour's maximum that is NOT the total maximum */
gother1 : first(listify(setdifference(setify(grades), {gmaxT, gmaxB, gmaxR})));
gother2 : first(listify(setdifference(setify(grades), {gmaxD, gmaxT, gminD})));
wrongkey4 : first(listify(setdifference({1,2,3,4,5}, {trend})));

/* ---------- text used in the worked solution ---------- */
tdc : "<td style='border:1px solid #999999; padding:3px 12px; text-align:center;'>";
thc : "<th style='border:1px solid #999999; padding:3px 12px; background:#eeeeee;'>";
tbl1 : sconcat("<table style='border-collapse:collapse; margin:6px 0;'><tr>", thc, "Grade</th>", thc, "Blue</th>", thc, "Red</th>", thc, "Total (blue + red)</th></tr>",
   apply(sconcat, create_list(sconcat("<tr>", tdc, string(grades[i]), "</td>", tdc, string(B[i]), "</td>", tdc, string(R[i]), "</td>", tdc, if is(grades[i]=gmaxT) then sconcat("<strong>", string(TT[i]), " (highest)</strong>") else string(TT[i]), "</td></tr>"), i, 1, 5)), "</table>");
tbl2 : sconcat("<table style='border-collapse:collapse; margin:6px 0;'><tr>", thc, "Grade</th>", thc, "Blue</th>", thc, "Red</th>", thc, "Difference (bigger &minus; smaller)</th></tr>",
   apply(sconcat, create_list(sconcat("<tr>", tdc, string(grades[i]), "</td>", tdc, string(B[i]), "</td>", tdc, string(R[i]), "</td>", tdc, if is(grades[i]=gmaxD) then sconcat("<strong>", string(DD[i]), " (greatest)</strong>") else string(DD[i]), "</td></tr>"), i, 1, 5)), "</table>");
sumTxt : sconcat(simplode(map(string, B), " + "), " = ", string(sumB));
steps4 : apply(sconcat, create_list(sconcat("<li>Grade ", string(6+i), " to grade ", string(7+i), ": red goes from ", string(R[i]), " to ", string(R[i+1]), ", which is ", if is(dif[i]>0) then sconcat("<strong>up</strong> by ", string(dif[i])) else sconcat("<strong>down</strong> by ", string(-dif[i])), ".</li>"), i, 1, 4));
trendTxt : if is(trend=1) then "Every step goes up, so the red line <strong>rises at every step</strong>."
      else if is(trend=2) then "Every step goes down, so the red line <strong>falls at every step</strong>."
      else if is(trend=3) then sconcat("The red line goes up first, reaches its highest value (", string(lmax(R)), ") in grade ", string(gmaxR), ", and then comes down: it <strong>rises to a peak and then falls</strong>. There is only one change of direction.")
      else if is(trend=4) then sconcat("The red line goes down first, reaches its lowest value (", string(lmin(R)), ") in grade ", string(gminR), ", and then goes up: it <strong>falls to a low point and then rises</strong>. There is only one change of direction.")
      else "The red line changes direction at least twice (it goes up and down more than once), so it <strong>zigzags</strong>.";
oneMax : sconcat("Grade ", string(gone), " has the highest number of ", if is(gone=gmaxB) then "blue" else "red", " pens (", string(if is(gone=gmaxB) then lmax(B) else lmax(R)), "), but that is only one colour. The question asks for the total of both.");
exl : [
 [1,  "Graph 5 shows that the totals are different from grade to grade. A grade with more students needs more pens, so this is a sensible reason."],
 [2,  "Graph 5 shows that the totals change between grades. More notes, homework and tests need more writing, so this is a sensible reason."],
 [3,  "The graph shows blue and red used in different amounts, and these change from grade to grade. Different writing and marking habits in different grades could explain that, so this is a sensible reason."],
 [4,  "Habits such as underlining, drawing diagrams and correcting work can change with age, which could change which pens are used, so this is a sensible reason."],
 [5,  sconcat("In Graph 1 the green band marks grade ", string(gmaxT), ", the grade with the highest total (", string(tmax), " pens). A larger grade or more written work could explain the large total, so this is a sensible reason.")],
 [11, sconcat("The totals in Graph 5 are not all the same: they range from ", string(lmin(TT)), " to ", string(tmax), ". Differences between grades are real and expected, so they are not a mistake.")],
 [12, sconcat("The graph shows blue and red used in different amounts: for example in grade 7 there are ", string(B[1]), " blue pens and ", string(R[1]), " red pens. The statement contradicts the data.")],
 [13, sconcat("The totals in Graph 5 do not change by a fixed amount from grade to grade (they go ", simplode(map(string, TT), ", "), "), so the number of pens is not decided only by the grade number.")],
 [21, if allR then "In Graph 1 the red line is above the blue line in every grade, so this statement fits the data and the reason is sensible." else "In Graph 1 the red line is not above the blue line in every grade (in some grades blue is higher), so this statement does not fit the data."],
 [22, if allB then "In Graph 1 the blue line is above the red line in every grade, so this statement fits the data and the reason is sensible." else "In Graph 1 the blue line is not above the red line in every grade (in some grades red is higher), so this statement does not fit the data."],
 [23, if is(trend=1) then "In Graph 4 every step of the red line goes up, so this statement fits the data and the reason is sensible." else "In Graph 4 the red line does not go up at every step, so this statement does not fit the data."],
 [24, if is(trend=2) then "In Graph 4 every step of the red line goes down, so this statement fits the data and the reason is sensible." else "In Graph 4 the red line does not go down at every step, so this statement does not fit the data."]
];
solhtml : apply(sconcat, map(lambda([r], sconcat("<p><strong>", if second(r) then "SENSIBLE REASON" else "NOT A SENSIBLE REASON", ".</strong> &ldquo;", third(r), "&rdquo;<br>", assoc(first(r), exl), "</p>")), ta5));
qnote : sconcat("B=", string(B), " R=", string(R), " u=", string(uu), " true:", string(tk), " false:", string(wk));

feedbackvariables.text:
sel : setify(ans5);
truth : setify(tk);
wrongticked : setdifference(sel, truth);
missed : setdifference(truth, sel);
nc : 6 - cardinality(symmdifference(sel, truth));
